def leftover_ga(row: Mapping[str, Any]) -> AreebValues:
    """Exact Gender Apparel table, then DTF-IronOn* / BG-* prefixes."""
    ga = cell(row.get("Gender Apparel"))
    if not ga:
        return AreebValues()
    hit = CL_GA_RULES.get(ga) or CL_GA_RULES_FOLD.get(ga.casefold())
    if hit:
        category, product_type = hit
        return AreebValues(
            category=category,
            product_type=product_type,
            source=SOURCE_CL_GA if (category or product_type) else SOURCE_NONE,
