def _ironon_style(ga: str) -> str:
    lower = ga.casefold()
    for prefix in ("dtf-ironon-", "dtf-ironon", "ironon-", "ironon"):
        if lower.startswith(prefix):
            rest = ga[len(prefix) :].lstrip("-")
            return rest or "Iron-On"
